te(player);check(player.getAirSupply()==10&&!player.hasEffect(MobEffects.NIGHT_VISION),"per-item disabled suppresses water powers");AwakenedArmorItem.toggle(stack);AwakenedArmorStatus.set(player,false);AwakenedHelm.update(player);check(!player.hasEffect(MobEffects.NIGHT_VISION),"global disabled suppresses powers");AwakenedArmorStatus.set(player,true);level.setBlockAndUpdate(pos,Blocks.LAVA.defaultBlockState());player.baseTick();check(player.isEyeInFluid(net.minecraft.tags.FluidTags.LAVA),"native lava eye fixture");AwakenedHelm.update(player);check(player.getAirSupply()==300&&player.hasEffect(MobEffects.BLINDNESS)&&!player.hasEffect(MobEffects.FIRE_RESISTANCE),"original lava blindness not invented fire resistance");player.removeAllEffects();AwakenedArmorStatus.set(player,false);AwakenedArmorItem.toggle(stack);player.getFoodData().setFoodLevel(10);player.tickCount=80;player.setHealth(10);AwakenedHelm.update(player);check(player.getHealth()==11,"passive healing independent both toggles");for(int food:new int[]{0,18,20}){player.getFoodData().setFoodLevel(food);player.setHealth(10);AwakenedHelm.update(player);check(player.getHealth()==10,"food boundaries "+food);}player.getFoodData().setFoodLevel(10);player.tickCount=81;AwakenedHelm.update(player);check(player.getHealth()==10,"exact80tick cadence");player.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);player.tickCount=160;AwakenedHelm.update(player);check(player.getHealth()==10,"unworn helmet no powers");
